/* Auto-generated speaking configs for ENGLISH_BOOK. Do not edit by hand. */
window.PRACTICE_EXTRA = Object.assign(window.PRACTICE_EXTRA || {}, {"sk1":{"caption":{"zh":"自我介绍常用句:点「听示范」听,再点「开口说」由浏览器给你打分。","en":"Introduction lines — press Listen for the model, then Speak to be scored by the browser."},"speaking":{"intro":{"zh":"跟读下面每一句自我介绍常用语:先听示范,再开口说,系统会识别你说的内容并按匹配度打分。","en":"Practise these introduction lines. Listen to the model, then speak — the browser will recognise what you say and score how well it matches."},"items":[{"en":"Hi, I'm Wei. It's nice to meet you.","zh":"你好,我是伟,很高兴认识你。","tip":{"zh":"重音落在 MEET;声调自然下降。","en":"Stress 'MEET'; let your voice fall at the end."}},{"en":"I'm from Chengdu, in the south-west of China.","zh":"我来自中国西南部的成都。","tip":{"zh":"在逗号处稍作停顿。","en":"Pause slightly at the comma."}},{"en":"I work as a software engineer at a tech company.","zh":"我在一家科技公司做软件工程师。","tip":{"zh":"work as 连读成 /wɜrkəz/。","en":"Link 'work as' → /wɜrkəz/."}},{"en":"I've been learning English for about five years.","zh":"我学英语大约五年了。","tip":{"zh":"I've been 弱读、快读。","en":"Say 'I've been' quickly and lightly."}},{"en":"In my free time, I enjoy hiking and photography.","zh":"空闲时,我喜欢徒步和摄影。","tip":{"zh":"photography 重音在第二音节:pho-TO-graphy。","en":"Stress the 2nd syllable: pho-TO-graphy."}},{"en":"Could you tell me a little about yourself?","zh":"能简单介绍一下你自己吗?","tip":{"zh":"疑问句句尾语调可微升。","en":"Let the pitch rise a little at the end."}},{"en":"It's a pleasure to finally meet you in person.","zh":"很高兴终于能当面见到你。","tip":{"zh":"pleasure 读 /ˈpleʒər/,不是 /pliː/。","en":"'pleasure' is /ˈpleʒər/, not /pliː/."}},{"en":"How do you two know each other?","zh":"你们俩是怎么认识的?","tip":{"zh":"know each other 连读顺畅。","en":"Link 'know each other' smoothly."}},{"en":"I'm really looking forward to working with you.","zh":"我非常期待和你共事。","tip":{"zh":"look forward to + 动名词(working)。","en":"'look forward to' + -ing (working)."}},{"en":"Sorry, could you repeat your name? I didn't catch it.","zh":"抱歉,能再说一次你的名字吗?我没听清。","tip":{"zh":"didn't 的 t 几乎不发音。","en":"The 't' in 'didn't' is barely pronounced."}}]}},"sk2":{"caption":{"zh":"闲聊社交常用句:点「听示范」听,再点「开口说」由浏览器给你打分。","en":"Small-talk lines — press Listen for the model, then Speak to be scored by the browser."},"speaking":{"intro":{"zh":"跟读下面这些日常闲聊和社交用语:先听示范,再开口说,系统会识别你说的内容并按匹配度打分。","en":"Practise these small-talk and socialising lines. Listen to the model, then speak — the browser will recognise what you say and score how well it matches."},"items":[{"en":"Hey, how's it going? Good to see you.","zh":"嘿,最近怎么样?见到你真好。","tip":{"zh":"how's it 连读成 /haʊzɪt/;句子轻快些。","en":"Link 'how's it' → /howzit/ and keep it light."}},{"en":"Long time no see! How have you been?","zh":"好久不见!你最近过得怎么样?","tip":{"zh":"四个词重音均匀:LONG TIME NO SEE。","en":"Even stress on all four words: LONG-TIME-NO-SEE."}},{"en":"Did you get up to anything nice this weekend?","zh":"这个周末有做什么有趣的事吗?","tip":{"zh":"Did you 连读成 /dɪdʒə/。","en":"'Did you' blends into /dɪdʒə/."}},{"en":"It's finally warming up — great weather for a walk.","zh":"天气终于暖和了——很适合散步。","tip":{"zh":"walk 读 /wɔːk/,l 不发音。","en":"'walk' is /wɔːk/ — the 'l' is silent."}},{"en":"What do you like to do in your spare time?","zh":"你空闲时喜欢做什么?","tip":{"zh":"What do you 快读弱化成 /wɒdʒə/。","en":"'What do you' reduces to /wɒdʒə/."}},{"en":"I'm really into photography at the moment.","zh":"我最近很迷摄影。","tip":{"zh":"photography 重音在第二音节:pho-TO-graphy。","en":"Stress the 2nd syllable: pho-TO-graphy."}},{"en":"Do you have any plans for the long weekend?","zh":"长周末你有什么安排吗?","tip":{"zh":"plans 的 s 读 /z/。","en":"The 's' in 'plans' sounds like /z/."}},{"en":"Anyway, I should get going. It was great catching up.","zh":"好了,我该走了。很高兴能聊聊近况。","tip":{"zh":"catching up 连读成 /kætʃɪŋʌp/;礼貌收尾。","en":"Link 'catching up'; a polite way to end a chat."}},{"en":"We should grab a coffee sometime soon.","zh":"我们改天该一起喝杯咖啡。","tip":{"zh":"grab a 连读成 /græbə/。","en":"Link 'grab a' → /græbə/."}},{"en":"The weather's been strange lately, hasn't it?","zh":"最近天气有点反常,是吧?","tip":{"zh":"反义疑问句 hasn't it 尾音上扬。","en":"Tag question 'hasn't it?' rises at the end."}},{"en":"How was your weekend? Did you do much?","zh":"周末过得怎么样?做了些什么吗?","tip":{"zh":"was your 连读成 /wɒʒər/。","en":"Link 'was your' → /wɒʒər/."}}]}},"sk3":{"caption":{"zh":"点单购物办事常用句:点「听示范」听,再点「开口说」由浏览器给你打分。","en":"Ordering & shopping lines — press Listen for the model, then Speak to be scored by the browser."},"speaking":{"intro":{"zh":"跟读下面这些在咖啡馆、餐厅和商店里作为顾客常说的话:先听示范,再开口说,系统会识别你说的内容并按匹配度打分。","en":"Practise these customer lines for cafés, restaurants and shops. Listen to the model, then speak — the browser will recognise what you say and score how well it matches."},"items":[{"en":"Could I get a medium latte, please?","zh":"我要一杯中杯拿铁,谢谢。","tip":{"zh":"Could I 连读成 /kʊdaɪ/;latte 读 /ˈlɑːteɪ/。","en":"Link 'Could I' → /kʊdaɪ/; 'latte' is /ˈlɑːteɪ/."}},{"en":"Do you have this in a medium?","zh":"这个有中号的吗?","tip":{"zh":"句尾 medium 语调上扬表疑问。","en":"Let 'medium' rise at the end — it's a question."}},{"en":"Can I pay by card?","zh":"我可以刷卡吗?","tip":{"zh":"pay by 顺滑连读,别停顿。","en":"Glide from 'pay' to 'by' with no pause."}},{"en":"Could I get the bill, please?","zh":"可以结账吗,谢谢。","tip":{"zh":"美式常说 check,英式说 bill。","en":"US usually says 'check'; UK says 'bill'."}},{"en":"I'd like a table for two, please.","zh":"我想要一张两人桌,谢谢。","tip":{"zh":"I'd like 弱读快读成 /aɪdlaɪk/。","en":"Say 'I'd like' quickly → /aɪdlaɪk/."}},{"en":"Excuse me, do you have this in another colour?","zh":"打扰一下,这个有别的颜色吗?","tip":{"zh":"Excuse me 重音在 CUSE。","en":"Stress 'exCUSE me'."}},{"en":"Sorry, where can I find the milk?","zh":"不好意思,牛奶在哪里?","tip":{"zh":"can I 弱读连读成 /kənaɪ/。","en":"'can I' reduces to /kənaɪ/."}},{"en":"Could I get this to go, please?","zh":"这个可以打包带走吗?","tip":{"zh":"to go = 外带;英式常说 takeaway。","en":"'to go' = takeaway (the UK term)."}},{"en":"I'd like to return this. Do I need the receipt?","zh":"我想退这件,需要小票吗?","tip":{"zh":"receipt 的 p 不发音:/rɪˈsiːt/。","en":"The 'p' in 'receipt' is silent: /rɪˈsiːt/."}},{"en":"Is this on sale, or is it full price?","zh":"这个是打折的,还是原价?","tip":{"zh":"on sale 连读;full 的 l 轻读。","en":"Link 'on sale'; keep the 'l' in 'full' soft."}},{"en":"Can I get a refund, or just an exchange?","zh":"我可以退款,还是只能换货?","tip":{"zh":"名词 refund 重音在前:RE-fund。","en":"The noun 'REfund' stresses the first syllable."}}]}},"sk4":{"caption":{"zh":"表达观点、赞同与反对:点「听示范」听,再点「开口说」由浏览器给你打分。","en":"Opinions, agreeing & disagreeing — press Listen for the model, then Speak to be scored by the browser."},"speaking":{"intro":{"zh":"跟读下面这些用来表达看法、赞同或委婉反对的常用句:先听示范,再开口说,系统会识别你说的内容并按匹配度打分。","en":"Practise these lines for giving opinions, agreeing and politely disagreeing. Listen to the model, then speak — the browser will recognise what you say and score how well it matches."},"items":[{"en":"In my opinion, remote work saves everyone a lot of time.","zh":"在我看来,远程办公能为大家省下很多时间。","tip":{"zh":"opinion 重音在第二音节:o-PIN-ion。","en":"Stress the 2nd syllable: o-PIN-ion."}},{"en":"I think we should hear both sides before we decide.","zh":"我觉得我们应该先听听双方再做决定。","tip":{"zh":"should 弱读成 /ʃəd/,快速带过。","en":"Weaken 'should' to /ʃəd/ and say it quickly."}},{"en":"That's a really good point — I hadn't thought of that.","zh":"这是个很好的观点,我之前没想到。","tip":{"zh":"thought 读 /θɔːt/,注意 th 咬舌音。","en":"'thought' is /θɔːt/ — mind the 'th'."}},{"en":"I see what you mean, but I still have some doubts.","zh":"我明白你的意思,但我还是有些疑虑。","tip":{"zh":"在 but 前稍作停顿,标示转折。","en":"Pause slightly before 'but' to mark the contrast."}},{"en":"I'm not sure I agree with that, to be honest.","zh":"老实说,我不太确定我同意那个说法。","tip":{"zh":"语调放软,委婉表达不同意。","en":"Keep the tone soft to disagree politely."}},{"en":"Absolutely! That's exactly how I feel about it.","zh":"完全同意!我就是这么觉得的。","tip":{"zh":"Absolutely 重音在首音节:AB-so-lutely,语气要强。","en":"Stress the first syllable: AB-so-lutely, with energy."}},{"en":"I couldn't agree more with what you just said.","zh":"我非常赞同你刚才说的话。","tip":{"zh":"couldn't 的 t 很轻;这句表示强烈赞同。","en":"The 't' in 'couldn't' is light; this means strong agreement."}},{"en":"Well, it depends on the situation, doesn't it?","zh":"嗯,这要看情况,对吧?","tip":{"zh":"反义疑问句尾用升调:doesn't it?","en":"Let the tag 'doesn't it?' rise at the end."}},{"en":"What do you think about working from home?","zh":"你怎么看在家办公这件事?","tip":{"zh":"think about 连读成 /θɪŋkəˈbaʊt/。","en":"Link 'think about' → /θɪŋkəˈbaʊt/."}},{"en":"I'm afraid I have to disagree with you there.","zh":"恐怕在那一点上我得跟你唱反调。","tip":{"zh":"I'm afraid 用来软化反对语气。","en":"'I'm afraid' softens the disagreement."}},{"en":"You might be right, but let's look at the facts.","zh":"你也许是对的,但我们还是看看事实吧。","tip":{"zh":"might 表示可能;let's 弱读、连读。","en":"'might' shows possibility; say 'let's' quickly."}}]}},"sk5":{"caption":{"zh":"打电话与约时间:点「听示范」听,再点「开口说」由浏览器给你打分。","en":"On the phone & making plans — press Listen for the model, then Speak to be scored by the browser."},"speaking":{"intro":{"zh":"跟读下面这些打电话、留言和约时间时的常用句:先听示范,再开口说,系统会识别你说的内容并按匹配度打分。","en":"Practise these lines for phone calls, taking messages and making plans. Listen to the model, then speak — the browser will recognise what you say and score how well it matches."},"items":[{"en":"Hello, could I speak to Mr Chen, please?","zh":"你好,请问陈先生在吗?","tip":{"zh":"could I 连读;句尾用礼貌的下降调。","en":"Link 'could I'; end with a polite falling tone."}},{"en":"He's not here right now. Can I take a message?","zh":"他现在不在。需要我帮你留言吗?","tip":{"zh":"message 重音在首音节:MES-sage。","en":"Stress the first syllable: MES-sage."}},{"en":"Are you free on Saturday afternoon by any chance?","zh":"你周六下午有空吗?","tip":{"zh":"free on 连读;句尾升调表询问。","en":"Link 'free on'; let the pitch rise to ask."}},{"en":"Shall we meet at the coffee shop near the station?","zh":"我们约在车站旁边那家咖啡店好吗?","tip":{"zh":"Shall we 是提议的常用开头。","en":"'Shall we' is a common way to suggest something."}},{"en":"Sorry, could you hold on a moment, please?","zh":"抱歉,能请你稍等一下吗?","tip":{"zh":"hold on 连读;语气保持礼貌。","en":"Link 'hold on'; keep the tone polite."}},{"en":"Let me check my calendar and get back to you.","zh":"我查一下日程再回复你。","tip":{"zh":"calendar 重音在首音节:CA-len-dar。","en":"Stress the first syllable: CA-len-dar."}},{"en":"Does two o'clock work for you on Friday?","zh":"周五两点对你合适吗?","tip":{"zh":"o'clock 的 o 弱读;work for 连读。","en":"Weaken the 'o' in 'o'clock'; link 'work for'."}},{"en":"I'm just calling to confirm our meeting tomorrow.","zh":"我打来只是想确认一下我们明天的会。","tip":{"zh":"confirm 重音在第二音节:con-FIRM。","en":"Stress the 2nd syllable: con-FIRM."}},{"en":"Great, so that's settled. See you on Friday then!","zh":"太好了,就这么定了,那周五见!","tip":{"zh":"settled 读 /ˈsetld/,t 很轻;语气愉快。","en":"'settled' is /ˈsetld/ with a light 't'; sound cheerful."}},{"en":"Sorry to bother you. Could you speak up a little?","zh":"不好意思打扰了,你能说大声一点吗?","tip":{"zh":"speak up 连读;a little 弱读带过。","en":"Link 'speak up'; say 'a little' lightly."}},{"en":"Thanks so much for calling. Have a lovely day!","zh":"非常感谢你的来电,祝你今天愉快!","tip":{"zh":"结束通话的礼貌语;语调温暖上扬。","en":"A warm way to end a call; keep the tone friendly."}}]}},"sk6":{"caption":{"zh":"面试常用回答:点「听示范」听语气,再点「开口说」由浏览器给你打分。","en":"Interview answers — press Listen for the tone, then Speak to be scored by the browser."},"speaking":{"intro":{"zh":"跟读这些面试里能直接用上的回答:先听示范的语气,再自信地开口说,系统会识别你说的内容并按匹配度打分。","en":"Practise these ready-to-use interview answers. Listen to the tone, then speak with confidence — the browser will recognise what you say and score how well it matches."},"items":[{"en":"Thank you for taking the time to meet me today.","zh":"谢谢您今天抽时间见我。","tip":{"zh":"语气温暖、不赶;重音落在 TIME。","en":"Warm and unhurried; stress 'TIME'."}},{"en":"I have three years of experience in digital marketing.","zh":"我有三年的数字营销经验。","tip":{"zh":"years of 连读;重音在 ex-PE-rience。","en":"Link 'years of'; stress 'ex-PE-rience'."}},{"en":"I'd describe myself as organised, calm and reliable.","zh":"我觉得自己做事有条理、沉稳、可靠。","tip":{"zh":"三个形容词之间各留短暂停顿。","en":"Pause briefly between the three adjectives."}},{"en":"My biggest strength is staying calm under pressure.","zh":"我最大的优势是在压力下保持冷静。","tip":{"zh":"strength 的 -ngth 收尾清晰;重音在 CALM。","en":"Finish 'strength' clearly; stress 'CALM'."}},{"en":"I work well with others and share ideas openly.","zh":"我善于与人合作,也乐于分享想法。","tip":{"zh":"work well 连读顺畅;openly 三音节。","en":"Link 'work well'; 'openly' has three syllables."}},{"en":"I'm a quick learner and I enjoy new challenges.","zh":"我学东西很快,也喜欢接受新挑战。","tip":{"zh":"quick learner 的 /k/ 要干脆利落。","en":"Crisp /k/ sounds in 'quick learner'."}},{"en":"I'm looking for a role where I can grow.","zh":"我想找一个能让我成长的岗位。","tip":{"zh":"grow 句尾语调上扬,听起来更有干劲。","en":"Lift the pitch on 'grow' to sound motivated."}},{"en":"Could you tell me more about this role?","zh":"能再多讲讲这个岗位吗?","tip":{"zh":"疑问句句尾语调可微升。","en":"Let the pitch rise a little at the end."}},{"en":"I'm confident I can add real value here.","zh":"我有信心能在这里创造实实在在的价值。","tip":{"zh":"confident 重音在第一音节;别赶 value。","en":"Stress 'CON-fident'; don't rush 'value'."}},{"en":"When would you like me to start?","zh":"您希望我什么时候入职?","tip":{"zh":"礼貌询问,句尾语调微升。","en":"A polite question — a slight rise at the end."}},{"en":"Thank you again for your time today.","zh":"再次感谢您今天抽出时间。","tip":{"zh":"真诚收尾,句尾语调平稳下降。","en":"Sincere close; let your voice fall at the end."}}]}}});
